draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // draw thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2 - 50, 30 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // draw question mark
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2 - 30);
  ctx.lineTo(W/2 + 90, H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 90, H/2 - 10);
  ctx.lineTo(W/2 + 80, H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2 - 10);
  ctx.lineTo(W/2 + 70, H/2);
  ctx.stroke();

  ctx.restore();
}
